CREATE FUNCTION salud_u.registrar_llegada_cita(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE a record;BEGIN PERFORM salud_u.requerir_administrativo(); SELECT * INTO a FROM salud_u.cita WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.estado<>'SCHEDULED' THEN RAISE EXCEPTION 'La cita no puede registrar llegada' USING ERRCODE='23514'; END IF; UPDATE salud_u.cita SET estado='CHECKED_IN' WHERE id=a.id; INSERT INTO salud_u.evento_estado_cita(id_cita,estado_anterior,estado_nuevo,id_actor) VALUES(a.id,'SCHEDULED','CHECKED_IN',salud_u.id_actor_actual()); END; $$;
CREATE FUNCTION salud_u.registrar_ausencia_cita(p_id uuid,p_reason text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=salud_u,pg_temp AS $$ DECLARE a record;BEGIN PERFORM salud_u.requerir_administrativo(); SELECT * INTO a FROM salud_u.cita WHERE id=p_id FOR UPDATE; IF NOT FOUND OR a.estado NOT IN('SCHEDULED','CHECKED_IN') THEN RAISE EXCEPTION 'La cita no puede marcarse como inasistencia' USING ERRCODE='23514'; END IF; UPDATE salud_u.cita SET estado='NO_SHOW' WHERE id=a.id; UPDATE salud_u.cupo_disponibilidad SET cantidad_reservada=cantidad_reservada-1,actualizado_en=now() WHERE id=a.id_cupo AND cantidad_reservada>0; INSERT INTO salud_u.evento_estado_cita(id_cita,estado_anterior,estado_nuevo,id_actor) VALUES(a.id,a.estado,'NO_SHOW',salud_u.id_actor_actual()); END; $$;
REVOKE ALL ON FUNCTION salud_u.registrar_llegada_cita(uuid),salud_u.registrar_ausencia_cita(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION salud_u.registrar_llegada_cita(uuid),salud_u.registrar_ausencia_cita(uuid,text) TO ${runtime_role};
